import base64,io,importlib.util,json,sys
from PIL import Image,ImageOps
spec=importlib.util.spec_from_file_location('normalizer','/workspace/scratch/8f544d546bb7/panelreply-ocr-next/workspace/ocr-preprocess.py')
m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
source=sys.stdin.buffer.read(8*1024*1024+1)
if len(source)>8*1024*1024:raise ValueError('input')
im=Image.open(io.BytesIO(source)).convert('RGB')
if im.width*im.height>16000000:raise ValueError('pixels')
mask,dark=m.ink_mask(im.convert('L'));ranges=[];start=None
if mask is not None:
 for y in range(im.height):
  active=mask.crop((0,y,im.width,y+1)).getbbox() is not None
  if active and start is None:start=y
  if not active and start is not None:ranges.append([start,y]);start=None
 if start is not None:ranges.append([start,im.height])
 heights=sorted(b-a for a,b in ranges)
 gap=max(2,int((heights[(len(heights)-1)//2] if heights else 0)*.4))
 grouped=[]
 for a,b in ranges:
  if grouped and a-grouped[-1][1]<=gap:grouped[-1][1]=b
  else:grouped.append([a,b])
 ranges=grouped
crops=[]
if 0<len(ranges)<=12:
 for a,b in ranges:
  x0,_,x1,_=mask.crop((0,a,im.width,b)).getbbox()
  crop=ImageOps.expand(im.crop((x0,a,x1,b)),border=10,fill='white' if dark else 'black')
  out=io.BytesIO();crop.save(out,format='PNG')
  crops.append({'bounds':[x0,a,x1,b],'data':base64.b64encode(out.getvalue()).decode('ascii')})
print(json.dumps({'bands':len(ranges),'crops':crops}))

'use strict';
const fs=require('node:fs');const {spawnSync}=require('node:child_process');const {performance}=require('node:perf_hooks');
const root='/workspace/scratch/8f544d546bb7/panelreply-ocr-next';const {createOcrService,parseTsv}=require(root+'/workspace/ocr.cjs');
const dir='/tmp/panelreply-ocr-20261123';const manifest=JSON.parse(fs.readFileSync(dir+'/manifest.json'));
const baseline=JSON.parse(fs.readFileSync('/tmp/panelreply-ocr-deskew-production-20261123.json'));const old=new Map(baseline.results.map(r=>[r.id,r]));
const recovered=new Set(['abbreviated--rotate-plus-1','abbreviated--rotate-plus-3','lowercase--rotate-minus-3','punctuation--rotate-minus-3']);
const cases=manifest.cases.filter(r=>!old.get(r.id).exact||['clear-sans','clear-serif','clear-mono','small-22px'].includes(r.condition)||recovered.has(r.id));
function run(binary,args,input){const r=spawnSync('/usr/bin/prlimit',['--as=1073741824:1073741824','--cpu=10:10','--core=0:0','--fsize=0:0','--nofile=64:64','--',binary,...args],{input,env:{PATH:'/usr/bin:/bin',LANG:'C.UTF-8',LC_ALL:'C.UTF-8',OMP_THREAD_LIMIT:'1',OMP_NUM_THREADS:'1'},cwd:'/',timeout:15000,maxBuffer:8*1024*1024+1024});if(r.status!==0)throw Error(r.stderr?.toString()||r.error);return r.stdout;}
(async()=>{const service=createOcrService();const results=[];try{
for(const fixture of cases){
 const started=performance.now(),source=fs.readFileSync(dir+'/'+fixture.file);
 const normalized=run('/usr/bin/python3',['-I','-B',root+'/workspace/ocr-preprocess.py'],source);const split=normalized.indexOf(10);const image=normalized.length>split+1?normalized.subarray(split+1):source;
 const {bands,crops}=JSON.parse(run('/usr/bin/python3',['-I','-B','/tmp/panelreply-ocr-line-crops-20261123.py'],image));
 const variants={};
 for(const psm of [7,13]){
  const began=performance.now();let parsed;
  if(crops.length){
   const rows=['level\tpage_num\tblock_num\tpar_num\tline_num\tword_num\tleft\ttop\twidth\theight\tconf\ttext'];
   for(let i=0;i<crops.length;i++){
    const raw=run('/usr/bin/tesseract',['stdin','stdout','-l','eng','--oem','1','--psm',String(psm),'tsv'],Buffer.from(crops[i].data,'base64')).toString();
    for(const line of raw.split('\n').slice(1)){
     if(!line.startsWith('5\t'))continue;const cells=line.split('\t');cells[1]=1;cells[2]=1;cells[3]=1;cells[4]=i+1;rows.push(cells.join('\t'));
    }
   }
   parsed=parseTsv(rows.join('\n')+'\n');
  }else parsed=await service.recognizeImage(source);
  const actual=parsed.candidates[0]?Object.fromEntries(['partNumber','manufacturer','description'].map(k=>[k,parsed.candidates[0][k]])):null;
  variants[psm]={actual,exact:['partNumber','manufacturer','description'].every(k=>(actual?.[k]||'')===(fixture.expected?.[k]||''))&&Boolean(actual)===Boolean(fixture.expected),rawText:parsed.rawText,recognitionMs:Math.round(performance.now()-began)};
 }
 results.push({id:fixture.id,baselineExact:old.get(fixture.id).exact,expected:fixture.expected,bands,cropBounds:crops.map(c=>c.bounds),variants,elapsedMs:Math.round(performance.now()-started)});
 if(results.length%10===0)console.log(results.length+'/'+cases.length);
}
fs.writeFileSync('/tmp/panelreply-ocr-line-screen-20261123.json',JSON.stringify(results,null,2));
for(const psm of [7,13])console.log(JSON.stringify({psm,cases:results.length,gains:results.filter(r=>r.variants[psm].exact&&!r.baselineExact).map(r=>r.id),losses:results.filter(r=>!r.variants[psm].exact&&r.baselineExact).map(r=>r.id),falsePositiveFields:results.reduce((n,r)=>n+['partNumber','manufacturer','description'].filter(k=>!r.expected?.[k]&&r.variants[psm].actual?.[k]).length,0)}));
}finally{await service.shutdown();}})();
